from pathlib import Path
import csv,json,hashlib,zipfile,platform,sys
import numpy as np
if hasattr(sys.stdout,'reconfigure'):sys.stdout.reconfigure(encoding='utf-8')
P=Path(__file__).resolve().parent;D=P/'results'
rows=list(csv.DictReader((D/'summary.csv').open()));pairs=list(csv.DictReader((D/'paired.csv').open()));checks=json.loads((D/'checks.json').read_text())
def get(sc,b,po,metric,delay=1):return next(r for r in rows if r['scenario']==sc and int(r['budget'])==b and r['policy']==po and r['metric']==metric and int(r['delay_multiplier'])==delay)
def val(sc,b,po,m,d=1):return float(get(sc,b,po,m,d)['mean'])
def fmt(r,n=3):return f"{float(r['mean']):.{n}f} [{float(r['ci_low']):.{n}f}; {float(r['ci_high']):.{n}f}]"
lines=['# Частичная наблюдаемость и задержки исполнения GP DFPR v3','',
'Подготовлен исполняемый исследовательский прототип новой постановки. Он управляет не только выбором конфигурации, но и тем, какие альтернативы оценивать при ограниченном бюджете. Это отдельный абстрактный эксперимент, а не обновлённая физическая RAN-модель и не внешняя валидация. Документы и данные v1/v2 сохранены.','',
'## Что уже реализовано','',
'- Три различных заключения: подтверждённая выполнимость, подтверждённая невыполнимость и недостаток информации.','- Интервалы наблюдений с ограниченной ошибкой; их расширение при устаревании по известной границе изменения KPI.','- Отдельный сертификат на момент завершения действия с задержкой 0/1/2/3 шага и её удвоением.','- Нижняя и верхняя границы минимально необходимой глубины изменения. Равенство границ подтверждает минимальную глубину, а не только допустимость выбранного действия.','- Явный статус recovery для действия с подтверждённым результатом в конце, но без гарантии выполнения цели во время ожидания.','- Честный UNCERTIFIED_RETAIN, когда подходящее действие не найдено: удержание текущей конфигурации не объявляется безопасным.','',
'Математическая постановка, шесть условных утверждений с доказательствами и границы возможного вывода приведены в THEORY.md. В частности, при холодном старте и отсутствии связей между альтернативами бюджет B < N не позволяет гарантированно доказать глобальную невыполнимость за один момент решения. Неисследованная альтернатива может оказаться выполнимой.','',
'## Выполненная проверка','',
f"Проверены {checks['controller_runs']} controller-runs и {checks['scored_steps']} шагов: 24 конфигурации, два сценария, бюджеты 1/2/4/8, три множителя задержек, 30 согласованных независимых seeds. Все настройки заданы до получения результатов. На один прогон приходится 300 оцениваемых шагов; дополнительный хвост нужен для проверки последних выданных команд.", '',
f"Выдано {checks['arrival_certificates']} сертификатов прибытия; нарушений этих сертификатов — {checks['arrival_certificate_failures']}. Ложных сертификатов физической невыполнимости — {checks['false_infeasibility_certificates']}. Проверки включения истинных величин в интервалы, границ глубины и бюджета прошли. Девять отдельных тестов включают контрпример для игнорирования задержки и проверку невозможности вывода по неисследованной альтернативе.", '',
'Эти нулевые ошибки следуют из правильности сертификатов при выполнении искусственно обеспеченных в модели границ ошибки и скорости изменения. Они не означают GPR = 1 и не являются сами по себе доказательством научной новизны или безопасности реальной сети.','',
'## Основные результаты при задержках 1 2 3 шага','',
'Certificate-directed, Round-robin и Uniform имеют одинаковую логику сертификатов, выбора и исполнения. Они различаются порядком оценивания альтернатив. Full-information получает все текущие значения точно, но также не знает будущего; это более информированный reference, а не доказанный оптимум GPR.','',
'| Сценарий | Бюджет | GPR Certificate-directed | GPR Round-robin | GPR Uniform | Оценок на шаг CD | UNKNOWN CD |',
'|---|---:|---:|---:|---:|---:|---:|']
for sc in ['Local','Outage']:
    for b in [1,2,4,8]:
        lines.append(f"| {sc} | {b} | {fmt(get(sc,b,'Certificate-directed','GPR'))} | {fmt(get(sc,b,'Round-robin','GPR'))} | {fmt(get(sc,b,'Uniform','GPR'))} | {val(sc,b,'Certificate-directed','queries_per_step'):.3f} | {100*val(sc,b,'Certificate-directed','unknown_rate'):.1f}% |")
lines+=['','Интервалы — pointwise 95% bootstrap по 30 прогонам. Для сравнения политик используются парные разности, а не перекрытие интервалов средних. Множественные сравнения не скорректированы. UNKNOWN считается по моментам принятия решения, GPR — по всем шагам, включая ожидание исполнения.','',
'| Сценарий | Бюджет | ΔGPR CD − RR | ΔGPR CD − Uniform |','|---|---:|---:|---:|']
for sc in ['Local','Outage']:
    for b in [1,2,4,8]:
        rs=[next(r for r in pairs if r['scenario']==sc and int(r['delay_multiplier'])==1 and int(r['budget'])==b and r['metric']=='GPR' and r['comparison']=='Certificate-directed minus '+po) for po in ['Round-robin','Uniform']]
        lines.append(f"| {sc} | {b} | {fmt(rs[0],4)} | {fmt(rs[1],4)} |")
lines+=['','**Преимущество эвристики Certificate-directed не подтверждено.** В Outage при стандартной задержке её GPR ниже Round-robin на 1.43 процентного пункта при B=2 и на 1.38 пункта при B=4; соответствующие парные интервалы не включают ноль. Это отрицательный результат для текущего порядка приобретения информации, который не скрывается. Гарантии корректности сертификатов разделяются всеми тремя acquisition policies и не доказывают преимущество одной из них.','',
'При B=1 все три стратегии совпадают: в активных неопределённых ситуациях свежая оценка текущего действия расходует весь бюджет и не оставляет запросов для альтернатив. Это ограничение данной реализации, а не доказательство невозможности любого управления с B=1.','',
'Все результаты с нулевой и удвоенной задержкой сохранены в results/summary.csv и paired.csv. Никакие случаи не исключались после просмотра. Показатели recovery/depth-certified в прогонах без команд записаны как 0 по вычислительной конвенции; они не означают проверенные события и требуют учёта числа commands.','',
'## Научный смысл и ограничения','',
'Новое ядро — проверяемый контракт acquisition → certificate → delayed execution. Это существенно отличается от прежнего эксперимента, где все KPI всех альтернатив предоставлялись сразу и переключение было мгновенным. При этом построение интервалов, safe exploration и выбор по приоритетам уже известны. Назвать всю комбинацию новым методом для журнала можно только после предметного сопоставления с ближайшими работами, а не по результату поиска похожего названия.','',
'Ближайшие ориентиры: [SafeOpt, ICML 2015](https://proceedings.mlr.press/v37/sui15.html), [GoOSE, NeurIPS 2019](https://proceedings.neurips.cc/paper/2019/hash/4f398cb9d6bc79ae567298335b51ba8a-Abstract.html) и [работа об infeasible safety certificates](https://arxiv.org/abs/2311.02133). Они упомянуты с конкретными границами сходства в THEORY.md; прямого экспериментального сравнения с ними в v3 нет.','',
'Самая сильная практическая предпосылка — возможность неинвазивно оценить KPI альтернативы с известной ограниченной ошибкой. Политика не получает неизмеренные истинные значения, но сам такой evaluator пока задан симулятором. Старые одиночные ColO-RAN трассы не предоставляют эти контрфактические наблюдения. Граница L также задана и соблюдается генератором; максимальное изменение, найденное на обучающих трассах, не стало бы гарантией для будущей эксплуатации.','',
'Во время задержки действует старая конфигурация. Прототип допускает recovery-команды и неопределённое удержание, поэтому заявляет только условную корректность указанных сертификатов, не непрерывное выполнение целей и не устойчивость динамической системы. Повреждение модели может не обнаружиться по пустому пересечению интервалов: этот тест обнаруживает лишь часть несогласованностей.','',
'## Следующий этап статьи','',
'1. Использовать THEORY.md как новое ядро Methods и сохранить прежние v1/v2 результаты как мотивацию, а не как подтверждение нового контроллера.','2. Проверить целевой evaluator на независимом simulator API или данных с действиями; измерять стоимость и задержку оценивания, а не только число запросов.','3. Добавить сильный active-feasibility comparator и вариации нарушения границ L/eta, сохранив различие формального сертификата и эмпирической оценки риска.','4. Не называть внешнюю валидацию завершённой до такой проверки. Текущий результат — готовая постановка, код и первичный контролируемый benchmark.','',
'## Воспроизведение','',
'Требуются Python 3.11+ и NumPy. На копии пакета выполните:','',
'```text','python test_prototype.py','python prototype.py','python make_report.py','```','',
'prototype.py перезаписывает results в своей папке. Протокол — PROTOCOL.md, формализация — THEORY.md, примеры журналов решений — results/events_*.json. Параметры и seeds находятся в исходном коде и протоколе. MANIFEST.json содержит контрольные суммы; открытых внешних данных этот новый абстрактный benchmark не использует.']
(P/'REPORT_RU.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
(P/'requirements.txt').write_text('numpy==2.3.5\n')
manifest={'date':'2026-09-20','python':sys.version,'numpy':np.__version__,'platform':platform.platform(),'checks':checks,'sha256':{str(f.relative_to(P)).replace('\\','/'):hashlib.sha256(f.read_bytes()).hexdigest() for f in sorted(P.rglob('*')) if f.is_file() and '__pycache__' not in str(f) and f.name!='MANIFEST.json'}}
(P/'MANIFEST.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
dest=P.parent/'GP_DFPR_Partial_Observation_v3.zip'
with zipfile.ZipFile(dest,'w',zipfile.ZIP_DEFLATED) as z:
    for f in sorted(P.rglob('*')):
        if f.is_file() and '__pycache__' not in str(f):z.write(f,str(Path(P.name)/f.relative_to(P)))
with zipfile.ZipFile(dest) as z:assert z.testzip() is None
print(dest,'bytes',dest.stat().st_size)
print('\n'.join(lines[25:43]))
